from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    dp = [[float('inf')] * N for _ in range(N)]
    dp[0][0] = grid[0][0]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # Right, Down, Left, Up

    for i in range(N):
        for j in range(N):
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < N and 0 <= nj < N:
                    dp[i][j] = min(dp[i][j], dp[ni][nj] + grid[i][j])

    min_path = []
    for i in range(N):
        for j in range(N):
            if dp[i][j] == dp[0][0] - grid[i][j] and len(min_path) < k:
                min_path.append(grid[i][j])
                if len(min_path) == k:
                    return min_path
    return min_path
```

