import re

def valid_date(date):
    # Regular expression to match the date format mm-dd-yyyy
    date_pattern = re.compile(r"^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])-\d{4}$")

    # Check if the date matches the pattern
    if not date_pattern.match(date):
        return False

    # Extract month, day, and year from the date string
    month, day, year = map(int, date.split('-'))

    # Check if the month is valid
    if month < 1 or month > 12:
        return False

    # Check if the day is valid for the given month
    if month in [4, 6, 9, 11] and day > 30:
        return False
    if month in [1, 3, 5, 7, 8, 10, 12] and day > 31:
        return False
    if month == 2 and (day > 29 or (day == 29 and not is_leap_year(year))):
        return False

    # Check if the year is valid
    if not is_leap_year(year):
        if day > 28:
            return False

    return True

def is_leap_year(year):
    """Check if a given year is a leap year."""
    return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)
