def minPath(grid, k):
    N = len(grid)
    dp = [[float('inf')] * N for _ in range(N)]
    dp[0][0] = grid[0][0]

    for i in range(N):
        for j in range(N):
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + grid[i][j])
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + grid[i][j])

    for i in range(N-1, -1, -1):
        for j in range(N-1, -1, -1):
            if i < N-1:
                dp[i][j] = min(dp[i][j], dp[i+1][j] + grid[i][j])
            if j < N-1:
                dp[i][j] = min(dp[i][j], dp[i][j+1] + grid[i][j])

    return dp[k-1][k-1]
```

