def tri(n):
    if n == 0:
        return []
    elif n == 1:
        return [3]
    elif n == 2:
        return [3, 1]

    tribonacci = [3, 1]
    for i in range(2, n):
        if i % 2 == 0:
            tribonacci.append(tribonacci[i-1] + tribonacci[i-2])
        else:
            tribonacci.append(tribonacci[i-1] + tribonacci[i-2] + tribonacci[i+1])

    return tribonacci
